<script>
document.querySelector('[data-wa-link]')?.addEventListener('click', () => {
    const message = encodeURIComponent('Hi Forus Freight, I would like to enquire about your freight services.');
    document.querySelector('[data-cta-url]').value = 'https://wa.me/{{ preg_replace('/[^0-9]/', '', config('forus.company.phone')) }}?text=' + message;
});
const preset = document.querySelector('[data-form-preset]');
const formPresets = { quote:['name','email','phone','company','service','origin','destination','message'], callback:['name','email','phone','message'], shipment:['name','email','phone','company','origin','destination','service','message'], contact:['name','email','phone','message'] };
preset?.addEventListener('change', () => { const fields=formPresets[preset.value]; if (!fields) return; document.querySelectorAll('.field-options input').forEach(input => input.checked=fields.includes(input.value)); });
const ctaPreset = document.querySelector('[data-cta-preset]');
const ctaLabel = document.querySelector('[data-cta-label]');
ctaPreset?.addEventListener('change', () => { if (ctaPreset.value !== 'custom') ctaLabel.value = ctaPreset.value; });
const mediumPreset = document.querySelector('[data-medium-preset]');
const mediumValue = document.querySelector('[data-medium-value]');
if (mediumPreset && mediumValue) {
    const existingMedium = mediumValue.value;
    if ([...mediumPreset.options].some(option => option.value === existingMedium)) mediumPreset.value = existingMedium;
    mediumPreset.addEventListener('change', () => { if (mediumPreset.value !== 'custom') mediumValue.value = mediumPreset.value; });
}
</script>
